local rows = text.values
rows["68:1158824567"]="이렇게 훌륭한  ⁇ 을 먹은 적은 없어요"
rows["68:116008285"]="내  ⁇ 을 좀 좀 챙겨줄 수 있어?"
rows["68:1160518082"]="저는 물건을 짓는 것을 좋아합니다. 물론, 더 많은 것을 폭발시키는 것도 좋아합니다."
rows["68:1164162450"]="나그렐이 이 소식을 듣기 까지 기다려!"
rows["68:1167891342"]="새들이 널 좋아해서 따라가겠다"
rows["68:1187707963"]="저는 사원의 한가운데에 있는 아프라사스트라스 신자님께 가고 싶습니다."
rows["68:1189626985"]="이 어려움은 지나갈 것이고, 그 때문에 우리는 더 강해질 것입니다."
rows["68:1192043378"]="반드시 복수해주십시오, 이방인이여... 녀석... 들에게... 지옥을..."
