rows["68:1194716411"]="넌 막대랑 딴데 있는 농민들 뿐이야"
rows["68:119755509"]="들어가세요, 들어보세요. 오늘 제가 드릴 게 있나요?"
rows["68:1205341402"]="그리고 붉은 크레인에서 더 나은 세상을 위한 희망의 빛나는 광선!"
rows["68:1212575957"]="젠키, 잠시 메인더스 스티드에 돌아가서?"
rows["68:1220621455"]="또한 모든 사람들의 가장 좋아하는 얼음 깃털 친구인 디피를 환영합니다!"
rows["68:122431626"]="오늘 우리가 어떻게 당신을 섬길 수 있을까요?"
rows["68:1225829010"]="왕실의  ⁇ 지스 하프맨은 당신이 찾고 있는 오크입니다."
rows["68:1227325317"]="너도 아름답다 보스, 최근 거울에 본 적이 있어?"
rows["68:1231483395"]="어둠의 소환자는 짧은 시간 동안 취약해, 이제 네 기회야!"
rows["68:1232803732"]="이 오크들이 우리를 잡을까봐 기다려라"
rows["68:1240377281"]="왜냐하면 그들은 그  ⁇ 귀한 정신 치료사와 많은 시간을 보내기 때문입니다!"
rows["68:1241863101"]="얼라이언스 카라반이 울음소리 밖으로 안내되어야 합니다."
rows["68:1243860746"]="더 이상한  ⁇ 을 채울 수 있을지도 몰라"
rows["68:124736800"]="조심해, 이 숲에는 식물보다 더 치명적인 것들이 있어요!"
rows["68:1248014489"]="우리는 여기에 합류하기 위해 왔습니다 얼라이언스- 우리는 당신의 황제에게 청문회를 요청합니다."
rows["68:1249476575"]="구경이나 해라, 노예. 고어게크가 바위돌기고릴라 다 해치운다!"
