rows["68:1282986071"]="해조류는 항상 태어나던 해변으로 돌아갑니다!"
rows["68:1299832132"]="안녕하세요, 영웅, 난 이미르자르의 군대를 전사들에게 팔고"
rows["68:1313734068"]="얼라이언스 카라반이 잊혀진 수영장에서 탈출해야 합니다."
rows["68:1317963275"]="시내 중간에 있는 우편 상자, 상권, 상단 반지, 숙소 옆에 있는"
