rows["702:944415091"]="안녕하세요, 제 이름은 테엘란 블러드워커입니다. 제 평생의 대부분을 마법의 예술에 대해 훈련하고 있습니다.$B$B보시다시피, 전 세계에 퍼져있는 고대, 강력한 유적이 있습니다. 제가 제 사람들을 중독으로부터 해방시키고 다시 통합시키려고 할 것입니다. 우리가 한때 자랑스럽고 굴복할 수 없는 인종으로 말이죠.$B$B마법은 받아들여져야 할 것이고, 저는 여러분에게 확신합니다. 제대로 된 가르침으로 부패 없이 활용될 수 있는 힘입니다.$B$B현재, 다른 인종 얼라이언스 그리고 심지어 호드 우리의 반 파괴된 수도를 위해 우리 종을 비웃고 있습니다. 태양광의 불상들이 여전히 서 있고,$B$B더 이상 안 돼"
rows["706:1947362575"]="우리의 존경을 얻기 위한 몇 가지 방법이 있습니다.$B$B우리는 Kun-Lai 정상에서 Firebough Nook에서 폭발에 대해 처리하고 있습니다.$B$B샤도파나 수도원도 곤경에 처해 있습니다.$B$B분노의 샤는 북쪽  ⁇  라이의 들들을 돌아다니며 이 전투를 물리치고 우리 군대의 존경심을 얻게 될 것이다.$B$B샤오프가 타운롱 스텝에서 증오의 샤를 쫓아다니며$B$B우리의 최고의 존경을 받고 싶다면 먼저 황금 로터스 상에서 존경받는 지위를 얻어야 합니다. 그 다음만 타운롱 스텝의 샤도파인 가리소에서 제 형제들과 자매들과 이야기하십시오."
rows["70:1000071525"]="아주 잘, 이빨에 피가 있어요?"
rows["70:1000846492"]="%s 시작 |cFFFF0404|Hspell:116711|h[불을 그려]|h|r 무기로!"
rows["70:1008537194"]="네, 내가 할 수 있는 요리법이 있어"
rows["70:1013558675"]="우린 총을 타고 다다 스컬지  ⁇ 드랙에서, 시작해!"
rows["70:1014204976"]="경고 없이 왔어 경비원들이 할 수 있는 일은 없었어"
rows["70:1014962733"]="지금 농사를 짓지 않고 있는 만큼, 이 방법은 시간을 보낼 수 있는 좋은 방법입니다!"
rows["70:1017015976"]="이 거란은 조금 더 오래 지속될 겁니다. 오그리마"
rows["70:1024460727"]="우리는 헐적에서 북쪽으로 볼 수 있습니다. 멀리 떨어진 곳으로 데려다줍니다."
rows["70:1034708317"]=" ⁇ 버스가 올 것 같아, 어서 가자!"
rows["70:1043687509"]="롤크 마니아가 널 몹시 공격할 때 어떻게 할 거야?"
rows["70:1049457888"]="모르고르 사령관, 당신의 친절한 협조에 고맙게 생각합니다. 이제 떠나야겠군요."
rows["70:1049780199"]="우리가 마지막으로 하는 일이면 이 학살의 바닥에 도달할 것입니다!"
rows["70:1051632056"]="지난 몇 달 동안 힘든 시간을 보냈어요"
rows["70:1054595283"]="너희는 과거의 사건으로부터 벗어나고 있나니 곧바로 돌아와"
rows["70:1055254669"]="먹거리를 먹는 것보다도 낫다 쉬어"
rows["70:105895134"]="여어, 거기 있는 친구! 가을 축제에 오신 걸 환영합니다. 이리 와서 몇 잔 걸치세요!"
rows["70:1060461692"]="해답은 없다... 우리에게 저주를 내린 건 바로 티탄이기 때문이다!"
rows["70:1067286520"]="아래의 구멍에 있는 마티드 보고는 들리지 않았어"
rows["70:1073736188"]="내 풍력 라이더들은 바렌스 열풍을 통해 빠르게 비행할 수 있도록 훈련받았습니다."
rows["70:1074008588"]="반란군이라고 말하시나요?"
rows["70:1074813050"]="은계약이 보내신가요?"
rows["70:1075518177"]="내가 경쟁하는 임무야 필요하다면 부품을 가지고 있을지도 몰라"
rows["70:1078903200"]="과잉 에너지를 마그마트론 단위로 돌려보내"
rows["70:1097213334"]="너희들의 노력은 헛되이였어, 침입자들이 의식은 거의 완성됐습니다."
rows["70:109931528"]="아시다시피, 이번이 어린이주일인데 어떻게 도와드릴 수 있을까요?"
rows["70:1102836901"]="국가 없이, 원인을 가지고 있지 않은 상태에서..."
rows["70:1104150468"]="감사합니다 얼라이언스 영웅이 되지만 다음엔, 나는 자비가 없을거야."
rows["70:1105812784"]="코보크에 대한 통제력이 약해지면서 더러운 쓰레기를 떠나라!"
rows["70:1111390684"]="이쪽은 알테락밸리 전투장이고, 양측 모두 여전히 싸우고 있습니다."
rows["70:1111427875"]="난 네가 나랑 얘기하고 싶은 사람과 혼동해 놓았어"
rows["70:1120703399"]="린이 숨겨진 마스터를 찾았다는 걸 아세요?"
rows["70:1124561531"]="저기 좀 보십시오! 살라다르의 수송관이로군요! 그자가 공허의 힘을 잘 관리하고 있군..."
rows["70:1128992679"]="나에겐 고통이 있지만, 난 마일고스를 죽인 것처럼 널 죽여야 돼"
rows["70:1131825768"]="다음 번 자이드 괴물을 볼 때, 난 그 괴물들을 찢어 버릴거야."
rows["70:1133720886"]="지픽이 내가 없으면 바로 블러프로 데려다 줄 거야"
rows["70:1136414043"]="목마른? 달콤하고 따뜻한 꿀벌 콩 한 잔 어때요?"
rows["70:1138205882"]="어쩌면 벨록과 레리쿼리는 둘 다 가지고 있을지도 몰라"
