rows["71:1415059366"]="전혀요. 죽어라 살펴봐도 어떻게 이걸 작동시키는지 전혀 모르겠어요."
rows["71:1423392125"]="너 직접 만든 거니?"
rows["71:1424213261"]="내 아내를 팔아주면 나도 빠져나올 거야"
rows["71:1426402503"]="페렐리 씨, 당신 말고도 이 상품을 감독하는 사람이 있습니까?"
rows["71:1441784975"]="우리 형제들이 북서쪽으로 떨어지고 있어"
