rows["71:1476461106"]="보인다. 끝없는 고통이... 보인다. 고통과 분노가... 내게는 모든 것이 보인다."
rows["71:1483094611"]="물은 생명을 만들지 못할 수도 있지만 적어도 내가 그것을 옮길 수 있게 해 줄 것입니다."
