rows["71:1572134843"]="나는 아우구스투스! 자네에게 필요한 건 뭐든 있지! 팔고 싶은 게 있으면 뭐든 다 사주겠네!"
rows["71:1572665802"]="덤벼 보시지, 이 오크들. 하지만 내가 쿠에에게 돌아가는 걸 막을 순 없을 걸!"
