rows["72:999959188"]="두 개의 명령이 급하게 이 파견에 기록된 것 같습니다."
rows["732:1779628869"]="내 아빠가 그 이야기를 내게 몇 번이나 말해줬을 거야!$B$B큰 가뭄 때, 시기는 힘들었습니다. 농부들은 농작물을 물로 흘리고 있었습니다. 너무 건조했습니다. 도시 전체가 굶주리고 갈증을 앓고 있었습니다.$B$B그래서  ⁇  농부의 할아버지는 밤중에 차를 포장하는 것 외에는 뭘 하니까?$B$B그는 무산 짐승을 타고 온 호수까지 오'쿠인라이 정상 기지까지 갔고, 그 바그런을 담아온 건조한 물 배럴로 뒤집어 버렸습니다.$B$B어떻게 할 수 있었지? 우리 마을 전체가 죽어있었어! 그는 그  ⁇ 진 바그런을 그의 농장으로 몰아넣고, 그의 무산이 현장에서 죽었어요!$B$B하지만 우리는 마을 전체에 충분한 물을 가지고 있었고 봄 수확도 있었습니다.$B$B반힐을 구했어, 윤의 할아버지가 그랬어!"
rows["73:1013876795"]="거대한 고대인들은 당신을 경계하고 있지만 동맹으로 이야기합니다."
rows["73:1016702575"]="도움을 요청하면 그림자 경비원이 응답할 거야"
rows["73:1017705093"]="내가 아는 모든 걸 다 말해줬어 계속 학대하는 건 말도 안 돼"
rows["73:1022118215"]="우리 조상들이 이 외부인과 그들의 폭력적인 방법으로부터 우리를 보호해 줄 수 있기를 바랍니다."
