rows["76:1152690535"]="정말 흥미진진한 이야기였어 이제 그 책에 먼지가 왜 너무 많았는지 알았습니다."
rows["76:1168165292"]="구가 여기 있는 게 아니잖아 어떻게 내려갈지 몰라"
rows["76:1179094780"]="술은 안 먹어?"
rows["76:1182265507"]="잘 봐라, 루카스 빛 특히 이 녀석은"
rows["76:1183618818"]="상황을 수습하라! 저기 불을 꺼라. 호드는 아직 끝나지 않았다!"
rows["76:1184832390"]="드라카리는 자기 땅을 파괴하고 있어! 녀석들은 자멸할 걸세... 곧 말이야, 친구."
rows["76:1185284598"]="우리 문을 열어주셔서 감사합니다 $p- 당신 존재로 우리를 존중해"
rows["76:1185823859"]="꿈꾸는 건 잠자리인가요? 아니면 현실의 공포로부터 탈출한 것일까?"
rows["76:1187947413"]="배신 트롤들이 라저힐을 공격했습니다"
rows["76:1190541409"]="정말? 왜 그렇게 할 거야, 왜소?"
rows["76:1191338819"]="이 곳을 떠날 때 죽을 거야 네 세상엔 아무것도 남지 않아"
rows["76:1213773501"]="여기 서서 더 가까이 갈 수 없어"
rows["76:1221837645"]="희망은 어디서나 꽃을 피울 수 있습니다. 잊혀진 숲의 어두운 곳에서도요."
rows["76:122259621"]="예언자 는 뭔가 잘못 된 것 을 알아차린 것 처럼 머리 를 약간 기울인다."
rows["76:1227185214"]="아, 저기 있네 용모의 전투 여녀"
rows["76:1231658004"]="내 새 친구, 네 마음 속의 혼란을 볼 수 있어"
rows["76:1235447039"]="으윽... 안 돼! 우리가 아는 거라곤 너희가 우리 방어구와 무기에다 군마까지 훔쳐갔다는 것뿐이야!"
rows["76:123878171"]="우린 무역으로 유명해요, 전쟁은 아닙니다. 내가 팔고 있는 것을 보고 싶으세요?"
rows["76:1250402963"]="리산은 동전을 던지고, 누가 알아차렸는지 확인하기 위해 주변을 둘러보았다."
rows["76:1254094111"]="페즈 호브노브의 이름으로 아이론 트리 클리어링으로 가는 사람이 기다리고 있어요"
rows["76:1266410751"]="어떻게 날 사랑할 수 있어?"
rows["76:1281362363"]="보이지 않는 길의 스키타를 잃었소"
rows["76:1285670269"]="데즈코, 이건 호드-  ⁇ 을 풀어야 해 얼라이언스."
rows["76:129160034"]="크레이븐! 나는 확실히 그렇지 않습니다! 우리는 전쟁 중이 아닙니다 ... 아."
rows["76:1292243935"]="내 계약은 당신을 위해 싸우기 위해서요, 레지옹의 비밀을 밝히기 위해서가 아닙니다."
rows["76:1294477343"]="워송 홀드의 제펠린이 도착했습니다."
rows["76:1306889607"]="그늘에서 그렇게 나오지 말고 다음엔 여자한테 경고해 "
rows["76:1306986225"]="제네, 나네, 나네..."
rows["76:1311191298"]="우린 몇 시간동안 이 안개 속에서 비행해 왔어요"
rows["76:1323678589"]="내 일종이 거의 끝났어, 좀 잠겨서 볼 수 있어"
rows["76:1325615909"]="멍청이들아, 맨티드의 힘을 공격해 내면 너희들의 죽음은 빨리 올 거야"
rows["76:1331846792"]="이 도시는 고향과는 전혀 다른 도시입니다.\010아, 친구, 어떻게 도와드릴까요?"
rows["76:1333108732"]="라스타칸 왕은 자란다라리 밑에서 트롤 부족을 통합할 계획이다"
rows["76:1347698579"]="배에서 떠나는 걸 봤어, 부드러운 피부!"
rows["76:1349382254"]="지난 몇 주 동안 가장 좋은 싸움이 됐어 나머지는 적들을 위해 남겨두겠다"
rows["76:1351942901"]="\"너가 나를 통제하기에는 너무 일찍이, 네가 최근에 게임을 그만뒀어\"."
rows["76:1361899834"]="마우고에 대해 경고하지 않았어, 워시프"
