rows["76:1368847658"]="더 나은 것, 역사, 고대 민족의 유물"
rows["76:1376885437"]="차들이 준비되어 있어, 그레이먼 왕의 말을 기다리고 있어요."
rows["76:1384001020"]="슬프지 마세요. 순환은 분명합니다."
rows["76:1386806681"]="오브시디언 디펜더는 과부하를 당했고, 폭발물에도 취약한 상태입니다!"
rows["76:1389751603"]="워치프이는 다크스피어를 넘지 않아 호드를 찢어놨어"
rows["76:1390688659"]="충분히, 당신은 큰 마조가 있습니다 Vol'jin."
rows["76:1391085315"]="여기 진짜 화염이 있고, 정말 당신을 태울 수 있어요!"
rows["76:1400984333"]="여기로 가는 길에 공원 구역에 갔는데 아무것도 남지 않았어\010"
rows["76:1417334030"]="그 야만족들에게 지지를 주지 않을 거야 내가 살아 있는 동안은 아냐"
rows["76:1430769433"]="짐승들끼리 정신없이 서로 물고 뜯는 모습을 보러 여기 온 건 아니오, 티리온 경."
rows["76:1431782330"]="쉽게 돈을 벌 수 있습니다. 위원회는 생존자 중 모든 사람들 사이에 균등하게 분포됩니다!\010"
rows["76:1431877518"]="거창한 놈, 이 헐적들은 똑같은데 다시 순환하고 있어"
