rows["76:1436788499"]="아뇨, 알지만 이제 친구들랑 안전해"
rows["76:1437280087"]="장로 돌나무껍질은 마법 사용을 방해하는 음파 효과로 방어에 기여합니다."
rows["76:1441156994"]="다지크가 돌아올 때마다 벌레들이 늘어나는 것 같다. 왜 줄어들지를 않는 거지?"
rows["76:144224820"]="모두 승선해! 오그리마행 비행선이 도착했어! 듀로타로 가실 분들은 모두 타라고!"
rows["76:1442288873"]="만약 네가 진짜로 짐승의 피부를 가져왔다면?"
rows["76:144300026"]="수홀루는 위대한 자들이 남겨둔 것인데, 당신은 그들을 타이탄이라고 부를 수도 있습니다."
rows["76:1446972492"]="너무 일찍, 하지만 선택은 없다... 그들은 테스트되어야 합니다! 지금 내 주요 피험자들을 직면!"
rows["76:1451539220"]="그걸 망치질이라고 하는 거냐? 이따위 풋내기를 어떻게 믿으란 말인가?"
rows["76:1471111660"]="한 사람이 말을 하면서 지혜가 거의 없고, 듣는 것만으로 지혜가 많이 얻는다."
rows["76:1482575481"]="사랑 때문에 뭐라도 할 수 있겠지만, 적어도 당장 안할 거야"
rows["76:1483446497"]="너도 똑똑한 사람만큼 친절해 낯선 사람을 돕는 건 행운이야"
rows["76:1500678487"]="장난감 스메랄드 뱀이 네 머리카락을 먹으려고 하고 뱉어 내려고"
rows["76:1502912223"]="다시 한번 감사해요, 친구. 우리는 당신의 이름을 우리 민족의 역사에 기억할 것입니다."
rows["76:1504148689"]="이 사람들은 겁쟁이야, 내 말을 들어봐!"
