rows["76:1525765560"]="언젠가 클라시가 제 계급을 높일 수 있어"
rows["76:152803728"]="네가 해소해야 할 일이 많군, 지터스 난 널 쉽게 풀어줄 수 없어"
rows["76:1532959555"]="호드은 이 잔혹한 행위에 대해 책임을 질 것입니다."
