rows["76:1547082530"]="위켓은 승리했다고 생각하니?"
rows["76:1551545285"]="'아마겟돈'급 방어 시스템 완전 작동!"
rows["76:1551806259"]="만약 우리의 적들이 우리를 밀어붙이고 싶다면, 우리는 그들을 땅에 몰아넣을 것이다!"
rows["76:155689006"]="거인들은 아즈하리트를 떨어뜨렸죠?"
rows["76:1563223408"]="더 많은 사람들이 부상을 구해 나가라"
rows["76:1567987345"]="오랜만에 읽은 가장 재미있는 이야기야"
rows["76:1568295740"]="목회자 훈련장님, 전쟁 구역 외곽으로 가서 그들을 찾아보세요."
rows["76:1572062648"]="바람에 떠다니는 사랑처럼 느껴지네"
rows["76:1578179215"]="트랜스모그리피케이션 및 빈 저장 서비스를 본 도시에서 찾을 수 있습니다."
