rows["76:1583933503"]="다음으로 스파링 연습을 지휘할 수 있는 석탑수 주석입니다"
rows["76:1584204315"]="걱정 마, 고레게크가 널 불에 태우지 않을거야."
rows["76:1587211280"]="물론, 산에 올라서 식물을 물을 마시면서도 신경 쓸 수 있어"
