rows["76:1592749842"]="어떻게 이럴 수가! 리치 왕께서 널 위한 멋진 계획이 있다고 하셨는데..."
rows["76:1593003645"]="당신의 기술 수준에 대한 간단한 스케마를 위해, Ghermas와 이야기하십시오."
