rows["76:1614439439"]="훌륭한 일이에요. 제가 여러분에게 줄 지식을 정말 받을 자격이 있습니다."
rows["76:162797281"]="더 오래 그들을 견딜 수 없었을 것 같아요\010내 감사의 마음을 가지고 있어요!"
rows["76:1630891704"]="네 녀석이 믿는 신이 누구든 자비를 베풀어 달라고 빌어라. 너에겐 그런 자비조차 없다는 걸 보여줄 테니..."
rows["76:1634255528"]="태마, 보고에 필요한 모든 걸 볼 수 있을 만큼 가까이 왔어?"
rows["76:1635152868"]="제 잔다라 악마의 옷은 없어서 대체할 수 있어?"
rows["76:1643565035"]="이 테스트는 간단합니다. 나무가 깨질 때까지 나무를 때려야 합니다."
rows["76:1650520007"]="때론 직접 나서야 할 때도 있는 법이지. 발라모어 샤날!"
