rows["76:1665481539"]="다시 다져진 우리 친선을 알리는 의미로 그대의 물건인 것을 돌려 주겠다..."
rows["76:1678720685"]="판다리아의 영들이 우리 위대한 십자군에서 우리를 지지하고 있습니다!"
rows["76:1685529715"]="곧 우리 모든 적들이 자비를 빌리거나 우리의 발 아래 뼈가 깨질 것입니다!"
rows["76:1691467576"]="우리 감사의 말씀을 드리겠습니다."
rows["76:1697068542"]="참을성 시험으로 늑대가 전사처럼 행동할 것인가?"
rows["76:1702691777"]="호랑이의 눈앞에 무장력을 보여줄 준비가 되셨습니까?"
rows["76:1708086095"]="공기는 |cFFF00000|Hspell:118077|h[Lightning Storm]|h|r 형태로  ⁇ 니다!"
rows["76:1709712936"]="근처 나무의 어두운 뿌리 밑에서 고대 공포가 깨어나고..."
rows["76:1714442427"]="멋지다 그럼 내 아이들이 이 필사자들을 찢어지는 것을 지켜보자"
rows["76:1720799589"]="날 겁주고, 악취를 냈다고 말했어요."
rows["76:1722878380"]="병력도 적고 너무 늦었습니다. 이미 방어선이 무너졌어요. 그들에게 우리는 기껏해야 작은 장애물에 불과하단 말입니다."
rows["76:1725134372"]="오늘 보여준 힘의 놀라운 실적이군요"
rows["76:1729522976"]="이 소식은 좋은 소식이니까, 사제님, 그들에게 돌아가세요. 하지만 이 말을 조심하세요."
rows["76:1730062831"]="나  ⁇ 다, 난 수직사야 오그르 드레스를 만드는 법을 가르쳐 줄래?"
rows["76:1730636902"]="대령, 여기 현저한 원주민들이 있습니다."
rows["76:1744947046"]="마스터가 이 침략을 알게 될 거야"
rows["76:1747746438"]="자기 전투를 치는 시간이야 괴물!"
rows["76:1748329196"]="카르타크는 한 번 큰 혀를 먹었다고 합니다."
rows["76:175798069"]="오, 여유있게 나와 이야기해줘서 문명적으로 논의하자"
rows["76:1780907337"]="이 동상은 안 윈푸르가 준 신의 묘사와 일치하지 않습니다."
rows["76:1783244007"]="<살살라비름은 너를 비웃고, 그 후 다시  ⁇ 한 음료수를 마시러 간다.>"
rows["76:1793161908"]="이 오래된 타이탄 기술은 샤를 자기처럼 행동하고 있습니다."
rows["76:1793531794"]="눈부신 시야가 아니니?$B$B할 일이 많고 시간이 많지 않아"
rows["76:1793689999"]="명령은 내놔, 난 테라바인에게 전전장에서 넘겨줄게!"
rows["76:179529941"]="당신은 |cFFFF0404|Hspell:116417|h[Arcane Resonance]|h|r에 의해 영향을 받았습니다!"
rows["76:1803938590"]="그리, 당신은 무작위로 빌그워터 항구로 불지 않을거야?"
rows["76:180496290"]="피즈닉... 여기서 뭘 하는 거지?! 역시 너를 살려두는 게 아니었어!"
rows["76:181603154"]="일리단은 돼먹지 않은 멍청이에 불과하다. 그를 무너뜨리고 아웃랜드를 다시 손에 넣으리라!"
rows["76:1818196529"]="잘했어, 보아, 이제 네 몸도 쓸 수 없어서 자유롭게 가"
rows["76:1825909866"]="사로나이트 증기가 한 덩어리가 되어 맹렬하게 소용돌이치며, 무시무시한 형상으로 변화합니다!"
rows["76:1833333359"]="네 무기를 나에게 가져오너라, 용사여. 그 주인의 영혼을 먹이리라!"
rows["76:183501173"]="항구만 점령하고 적은 몰려났어"
rows["76:184070723"]="당신은 |cFFFF4809|Hspell:116417|h[Arcane Resonance]|h|r에 의해 영향을 받았습니다!"
rows["76:1842203988"]="우르속, 우르솔의 형제이자 펄볼그 부족의 수호자여... 모습을 보이시오!"
rows["76:1843077498"]="아니다, 내 아들아. 녀석들은 얼라이언스 군인이다. 우리의 원수지."
rows["76:1843326182"]="내가 아는 한 남아있는 유일한 흑인 드래곤은 나뿐이야"
rows["76:184485241"]="미스터, 선물은 좋아해요?"
rows["76:1848629607"]="친구, 무산 짐승들을 겁에 질릴 만큼 소음을 내리는 거야"
rows["76:1854065409"]="우트라시온과 그의 하위군을 싸우기 위해 위르메스트 성전 정상으로 데려가"
rows["76:1855163125"]="물어보는 생각은 싫어요 아제로스 도움을 요청하지만 선택의 여지가 거의 없습니다."
rows["76:1855521934"]="저랑 같이 가봐, 잃어버린 영혼들의 신원을 방문했고"
rows["76:1876804462"]="이 옷은 누구의 손으로 엮여있었는지 물어볼 수 있겠죠?"
rows["76:1879127981"]="...내가 무슨 일이 일어나고 있는지 이해한다고 생각해요. 적어도 내 자유의지가 남아있어요."
rows["76:1883271419"]="이런 노동 조건은 끔찍해요 몇 시간 동안 맥주 휴식을 취하지 않았죠!"
rows["76:1883569926"]="내 아들 디온은 하루 종일 들판에서 일하며 열심히 일해 엄마를 자랑스럽게 해"
rows["76:1886839889"]="그래서, 정말 감사해요. 이 무서운 정글에 나와 함께 데려갔다는 걸"
rows["76:1889436795"]="리 페이 선생의 목소리는 \"어디서 다시 만나게 될 것\"이라고 울린다."
rows["76:1892932722"]="아빠는 전쟁노래의 전투에서 언제 돌아오실까? 너무 오래됐어..."
rows["76:189973855"]="우린 포위되어 있어 난 배신자들을 멀리하고 있는 동안 승진자를 보내라"
rows["76:190028602"]="타이란데는 경고했지... 그녀는... 그녀는 빛이 되기 전에 엄청난 어둠이 있을 것이라고 말했다."
rows["76:1903139175"]="그것 참 걱정스러운 소식이군. 부관, 당장 가서 이 문제를 처리하도록!"
rows["76:1909017791"]="%s 생존한 짐승들을 보고 울고 치열하게 싸우고 있습니다!"
rows["76:1922223818"]="이게 무슨 짓인가?! 그만두게! 놈들이 말한 수고비의 두 배를 주겠네!"
rows["76:1923220171"]="군인님, 이제 우리 곁에 있는 선조들이 산이 치유됐습니다."
rows["76:1926787109"]="스코피언을 조심해, 그는 친절한 것처럼 보일 수도 있지만 그는 전투에서 짐승입니다!"
rows["76:1928865824"]="안녕하세요, 새가신가요, 집도 잃었나요?"
rows["76:1935865715"]="항상 비관적이군요. 그럴 가능성은 전혀 없답니다."
rows["76:1944444599"]="악마, 날 속일 수 없어 내 믿음이 강화되듯이 네 힘이 줄어들게"
rows["76:1953167728"]="당신은 정말 전투의 마스터입니다."
rows["76:1955984794"]="브란 브론즈비어드, 환영한다. 난 이 신전의 수호자가 남긴 잔재이다."
rows["76:1961800033"]="%s의 부드러운 목소리는 안개로 흘러들어갑니다. \"내가 항상 너를 사랑한다는 것을 알\"..."
rows["76:1966225270"]="난 가난한 작은 괴물이고, 자본이 없어..."
rows["76:1972298656"]="네가 가장 싫어하는 것만으로 네 영혼이 찢어질 수 있기를, 젊은 왕자여."
rows["76:1982472212"]="발할라스의 전사한 영웅들이 땅속에서 일어나 다시 전투를 벌이려고 합니다!"
rows["76:1982739420"]="이 사람들은 당신의 잔인한 노예가 되지 않을 것입니다 호드- 내가 허락하지 않을거야!"
rows["76:1989278478"]="성모 스톰브로우는 엘윈 숲에서 골드샤이어 마을에 가장 가능성이 높습니다."
rows["76:1989412800"]="플레쉬브르크스는 더 이상 리치 왕의 군대에 군인을 생산하지 않을 것입니다."
rows["76:1999637088"]="난 죽은 게 아니야, 오래 안되네, 내 아버지는 날 구해줄 거야"
rows["76:2013614513"]="코타콘이 여기서 뭐하는 거야?$B$B왜 그녀는 귀여운 작은 활을 입고 있는거야?"
rows["76:2015431100"]="내가 권한을 보여주지, 이 망할 기계야. 자, 여기 노르간논의 쐐기돌이다!"
rows["76:2021282254"]="이제, 내가 의식을 마치고 짐승을 네 반에 돌릴 때 지켜보게 될 거야!"
rows["76:2026634037"]=" ⁇ 은 도구, 맛있는 당근, 모두  ⁇ 젠에게"
rows["76:2028449873"]="우리 조상들의 영들이 우리를 지켜보고 이 전투에서 도와줄 것입니다."
rows["76:2030447290"]="우리는 결코 힘을 잃지 않는다! 난 우리의 미래를 지켜왔다! 너희는 나와 함께 영광을 누리리라!"
rows["76:2037093398"]="아달은 오늘 우리의 후원자들에게 전해야 할 진실에 대해 내 마음을 열어주었습니다."
rows["76:2039317700"]="넌 눈부신 똥구멍이잖아"
rows["76:2039779557"]="네, 진짜 똑똑한 사람이야, 슬립키크"
rows["76:2048064414"]="이 젊은 투스카르는 전투에서 죽었지, 익사한 것보다는"
rows["76:2050045880"]="달 축제의 풀달 기간 동안 우리는 기념 빛 엘루네의"
rows["76:2053632845"]="곧 또 다른 유물이 우리 수비자들에게 전해질 것이라는 소식을 전하라"
rows["76:2059920388"]="더 이상 변명하지 마, 황후여 이 멍청이를 없애라 아니면 내가 직접 죽여버리겠어!"
rows["76:2068538847"]="와! 진짜 위대한 자야? 수세이가 진짜 위대한 자를 만났을 줄은 생각도 못했어!"
rows["76:2073397833"]="친구, 무산 짐승들을 겁에 질릴 만큼 소음을 내리는 거야"
rows["76:2086471064"]="모고들은 피와 철의 무기를 만들어 내며, 그들의 칼은 죽음을 먹는다."
rows["76:2094226413"]="재조합하는 동안 그들을 혼란에 던져 주시오. 지옥의 눈은 당신을 향해 있습니다!"
rows["76:2103364445"]="그래서 지옥의 거만성으로 마지막 꼴이 나왔어요"
rows["76:2118328539"]="얼라이언스가 파다렌에게 한 모든 일을 해도 여전히 여기로 가게 됩니다!"
rows["76:2120242073"]="내 사랑하는 친구, 오렴, 어둡의 집까지 가자"
rows["76:2120633418"]="다시 안녕하세요. 더 많은 환상이 다가오고 있습니다."
rows["76:212649389"]="200마력, 복합연방 엔진, 수정된 흐름 가축!"
rows["76:2132203081"]="발티어, 제 젠다라 마드캡의 망틀을 잃었어 대체가 있어?"
rows["76:2137253494"]="우리는 아타스를 꺾을 거야! 스컬지는 호드의 힘을 견딜 수 없어!"
rows["76:213787036"]="지상의 반지는 원소의 힘과 위대함을 보존하려고 합니다."
rows["76:215265577"]="누가 믿을 수 있는지 알 수 없는데, 나만 있으면 알 수 있을 겁니다."
rows["76:215273379"]="내 죽은 손에서 다라란의 원숭이의 유물을 빼내야 할 거야!"
rows["76:216767390"]="장로 무쇠줄기 조사 결과, 식물체에 기인한 이동 불가 효과가 관찰되었습니다."
rows["76:231036721"]="길 건너에 있는 블러드 엘프들이 내가 첩자라고 오해하지 말아야 할 텐데!"
rows["76:241006316"]="항복해 우린 너희들을 살게 해 주겠네"
rows["76:244809764"]=" ⁇ 과 다른 천체들의 존재에 있는 것이 정말 영광입니다."
rows["76:253947216"]="좋은 쇼, 다른 건 다치면 알려줘"
rows["76:254083624"]="이 시험 을 겪으면서, 당신 과 뱀 의 관계는 더욱 강화 될 것 입니다."
rows["76:254648653"]="야르, 내 사랑으로 굳게 서라. 나만큼 능력 있는 배구꾼이 더 없지!"
rows["76:257302119"]="내 고백자의 옷의 일부를 되찾는데 도움이 필요해요 알타비임"
rows["76:260412784"]="온몸으로 나의 힘을 느껴라! 나의 힘에 도취하라! 호드의 영광을 위해 싸우라!"
rows["76:261857141"]="어서 두려워하지 마요, 그림자가 오든 빛이 오든 물은 항상 흐르게 될 것입니다."
rows["76:266439137"]="당신들을 안전하게 데려가면 블루 드래곤 비행의 세력을 배제할 수 있을 겁니다"
rows["76:270610447"]="아니, 살리, 상처가 낫게 돼 지금 백색  ⁇ 을 찾아야 해"
rows["76:276022746"]="내 경비원들이 쓸모없어 내가 직접 널 돌봐야겠어"
rows["76:280120527"]="십자군 재판에서 성공한 후에 다시 오세요."
rows["76:280325088"]=" ⁇ 이 너무 강력해!"
rows["76:28368186"]="내 뒤를 지켜줘서 반가워 난 가로쉬의 똥구멍이 싫어요"
rows["76:291406185"]="붕괴 직후 무너져 내렸어요 지금 조사중입니다"
rows["76:292466019"]="아타스는 죽음의 기사들을 만들 때 실패했지"
rows["76:29350040"]="너무 멀리 갔어 뱀이여, 네가 저지른 죄 때문에 고통받아"
rows["76:297503983"]="드래곤을 타고 있는 강아지 본 적 없어?"
rows["76:307385725"]="일어나라, 나의 천사들아 너희 외치는 오그리마의 거리를 공포로 가득 채우게 하라"
rows["76:30900003"]="공격을 막아보십시오, 풋내기 양반! 혈기사가 될 자격이 있는지 한번 봅시다!"
rows["76:310134620"]="진짜 영웅처럼 싸웠어요 리 리와 연락을 해야 해요"
rows["76:315774802"]="왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜 왜"
rows["76:316064258"]="내가 단지 1단장 폭발물을 심어줄 거라고 생각했지?"
rows["76:32847350"]="나이를 헛드셨군요! 그렇다면 오시지요. 와서 스컬지의 힘에 맞서 보십시오!"
rows["76:330129417"]="생각해 봐라, 발굴조사단장. 하지만 우리도 속히 행동을 취해야 하니 결정을 빨리 내려야 한다."
rows["76:343236541"]="하룻강아지가 숨을 차례다! 꼭꼭 숨어라... 머리카락 보일라!"
rows["76:351370207"]="이번 대회가 생각보다 더 쉬워질 거야"
rows["76:362611440"]=" ⁇ 스파이스트 강, 위더바크 강 함께 적들을 물리칠 수 있어"
rows["76:364553164"]="칼로든 마법으로든 피를 흘리면, 공격은 강해지고 적은 약해지리라."
rows["76:367243284"]="천만 명이 하늘을 통해 우리를 지켜보고 있는 곳..."
rows["76:369037735"]="참을성, 장군. 빛 좋은 믿음으로 Shattrath에 들어가는 모든 사람들을 포옹합니다."
rows["76:370031066"]="미치기 말아요, 개구리 가득한 그릇이에요."
rows["76:370969047"]="호드가 왔어요. 이제 진짜 지도자가 된 시간입니다."
rows["76:380695380"]="코도하이드 스피어 워커스, 당신이 원하는 건 그 드래그 중간에 있는 것"
rows["76:393129369"]="저는 중간 속임수와 함께 액션 트리거 스플라인을 위한 경로 평행 테스트입니다."
rows["76:394295431"]="수호루는 스파크터치에게 다른 오라클 부족보다 더 많이 나타납니다."
rows["76:394620502"]="어떻게 볼 수 있어?$B$B그 일을 해야 할 거야"
rows["76:394861765"]="안 알지만, 그 이유는 분명합니다."
rows["76:395718005"]="아스펙트의 진정한 아이처럼 말하며 항상 세상을 바꾸려고 노력합니다"
rows["76:401955913"]="무덤에서 많은 감정이 쏟아져 나오고 분노와 두려움이 너무 많았어요"
rows["76:402781424"]="저거 제 작은 지르시야!"
