rows["77:2059349608"]="우리의 작업은 안정적이고 지루했지만 동상은 거의 완성되었습니다."
rows["77:2066235441"]="인내심, 타이란데, 우리는 승리를 거둘 것이지만 준비되지 않은 것은 아닙니다."
